function ApiDrawer({section,onClose,notify}){const code=`<ShuLan${section.title.replace(/\s/g,'')}\n  variant="primary"\n  size="default"\n  disabled={false}\n/>`;return <div className="drawer-backdrop" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><aside className="api-drawer"><header><div><small>COMPONENT API</small><h2>{section.title}</h2></div><button className="icon-btn" onClick={onClose}><X/></button></header><p>{section.desc}</p><h3>Props</h3>{[['variant','primary | secondary'],['size','tiny | small | default | large'],['disabled','boolean'],['onClick','() => void']].map(x=><div className="prop-row" key={x[0]}><code>{x[0]}</code><span>{x[1]}</span></div>)}<h3>使用示例</h3><pre>{code}</pre><button className="secondary copy-code" onClick={()=>{navigator.clipboard?.writeText(code);notify('示例代码已复制')}}><Copy/>复制代码</button></aside></div>}

function PromptImageOutput({notify}){const [selected,setSelected]=useState(0);const [ratio,setRatio]=useState('1:1');const [generating,setGenerating]=useState(false);const images=[['暮光城市','image-a'],['薄荷空间','image-b'],['珊瑚地貌','image-c'],['午夜产品','image-d']];const generate=()=>{setGenerating(true);setTimeout(()=>{setGenerating(false);notify('已生成 4 张新图片')},1500)};return <div className="media-output image-output"><div className="media-header"><div><span className="agent-avatar flare"><Image/></span><div><b>ShuLan 图片生成器</b><small>{generating?'正在生成候选图片…':'已完成 · 4 个候选结果'}</small></div></div><div className="format-control">{['1:1','4:3','16:9'].map(x=><button className={ratio===x?'active':''} onClick={()=>setRatio(x)} key={x}>{x}</button>)}</div></div><div className="media-prompt"><Sparkles/><div><small>生成提示词</small><p>未来主义产品摄影，柔和的薄荷绿光线，极简空间，细腻材质，高级商业视觉。</p></div><button onClick={()=>notify('提示词已复制')}><Copy/>复制</button></div>{generating?<div className="generation-loading"><span className="spinner"/><b>正在生成图片</b><p>正在渲染光影、材质和构图…</p></div>:<><div className={`image-results ratio-${ratio.replace(':','-')}`}>{images.map(([name,cls],i)=><button className={`generated-image ${cls} ${selected===i?'selected':''}`} onClick={()=>setSelected(i)} key={name}><span>{selected===i?<Check/>:i+1}</span><b>{name}</b></button>)}</div><div className="media-actions"><div><span>已选择：<b>{images[selected][0]}</b></span><button className="secondary" onClick={()=>notify('已打开图片编辑器')}><SlidersHorizontal/>继续编辑</button></div><button className="secondary" onClick={generate}><RotateCcw/>重新生成</button><button className="primary" onClick={()=>notify(`${images[selected][0]} 已下载`)}><Download/>下载图片</button></div></>}</div>}

function PromptVideoOutput({notify}){const [playing,setPlaying]=useState(false);const [progress,setProgress]=useState(38);const [variant,setVariant]=useState(0);const [generating,setGenerating]=useState(false);const generate=()=>{setGenerating(true);setTimeout(()=>{setGenerating(false);setProgress(0);notify('新的视频版本已生成')},1600)};return <div className="media-output video-output"><div className="media-header"><div><span className="agent-avatar flare"><GalleryHorizontalEnd/></span><div><b>ShuLan 视频生成器</b><small>{generating?'正在生成视频…':'已完成 · 1080P · 8 秒'}</small></div></div><div className="video-variants">{['版本 1','版本 2','版本 3'].map((x,i)=><button className={variant===i?'active':''} onClick={()=>setVariant(i)} key={x}>{x}</button>)}</div></div><div className="media-prompt"><Sparkles/><div><small>视频提示词</small><p>镜头缓慢推进，展示透明气泡水瓶，背景光线由蓝色过渡到紫色，液体气泡自然上升。</p></div><button onClick={()=>notify('视频提示词已复制')}><Copy/>复制</button></div>{generating?<div className="generation-loading video-loading"><span className="spinner"/><b>正在合成视频</b><p>生成关键帧并处理镜头运动…</p></div>:<><div className={`video-canvas video-version-${variant}`}><div className="video-scene"><span className="product-bottle"/><i/><i/><i/></div><button className="play-button" onClick={()=>setPlaying(!playing)}>{playing?<Pause/>:<Play/>}</button><button className="fullscreen" onClick={()=>notify('已进入全屏预览')}><Maximize2/></button><div className="video-timeline"><button onClick={()=>setPlaying(!playing)}>{playing?<Pause/>:<Play/>}</button><span>00:0{Math.round(progress/13)} / 00:08</span><div onClick={e=>setProgress(Math.round(e.nativeEvent.offsetX/e.currentTarget.clientWidth*100))}><i style={{width:`${progress}%`}}/></div><b>1080P</b></div></div><div className="shot-list"><div><span>01</span><div><b>产品入场</b><small>0:00 — 0:02</small></div><i/></div><div><span>02</span><div><b>光线过渡</b><small>0:02 — 0:05</small></div><i/></div><div><span>03</span><div><b>品牌定格</b><small>0:05 — 0:08</small></div><i/></div></div><div className="media-actions"><div><span>当前版本：<b>版本 {variant+1}</b></span><button className="secondary" onClick={()=>notify('已打开视频编辑器')}><SlidersHorizontal/>编辑镜头</button></div><button className="secondary" onClick={generate}><RotateCcw/>重新生成</button><button className="primary" onClick={()=>notify('视频已导出')}><Download/>导出视频</button></div></>}</div>}

function PromptOutputHub({notify}){const [format,setFormat]=useState('text');const formats=[['text',MessageSquareText,'文本输出','气泡信息流与结构化文本'],['image',Image,'图片生成','候选图片与编辑操作'],['video',GalleryHorizontalEnd,'视频生成','播放器、镜头与导出']];return <div className="output-hub"><div className="output-format-tabs">{formats.map(([id,Icon,title,desc])=><button className={format===id?'active':''} onClick={()=>setFormat(id)} key={id}><Icon/><span><b>{title}</b><small>{desc}</small></span>{format===id&&<Check/>}</button>)}</div><div className="output-format-content" key={format}>{format==='text'?<PromptOutput notify={notify}/>:format==='image'?<PromptImageOutput notify={notify}/>:<PromptVideoOutput notify={notify}/>}</div></div>}

function GenerationRecordHeader({kind,Icon,prompt,model,attachments}){
 const [popoverBelow,setPopoverBelow]=useState({})
 const hasPreview=prompt.length>20
 const isImage=kind.startsWith('图片')
 const skill=isImage?'图片生成':'视频生成'
 const ratio=isImage?'1:1 / 3:4 / 4:3':'16:9'
 const resolution=isImage?'2K':'1080P'
 const attachmentCount=attachments??(isImage?3:prompt.length>500?4:prompt.length>45?3:prompt.length>20?2:1)
 const positionPopover=(index,event)=>{const rect=event.currentTarget.getBoundingClientRect();setPopoverBelow(value=>({...value,[index]:rect.top<420}))}
 const copyPrompt=()=>navigator.clipboard?.writeText(prompt)
 const ParameterInfo=()=> <>
  <button className="copy-prompt" onClick={copyPrompt} title="复制提示词" aria-label="复制提示词"><Copy/>复制提示词</button><i/>
  <span><WandSparkles/>{skill}</span><i/>
  <span><Bot/>{model}</span><i/>
  <span><Crop/>{ratio}</span><i/>
  <span><Monitor/>{resolution}</span>
  {!isImage&&<><i/><span><Timer/>8 秒</span></>}
 </>
 return <div className="generation-record-head"><div className={`generation-reference-list ${attachmentCount>=2?'is-stacked':''}`} aria-label={`${attachmentCount} 个附件`}>{Array.from({length:attachmentCount},(_,index)=><span className={`generation-reference ${isImage?'reference-image':'reference-video'} ${popoverBelow[index]?'popover-below':'popover-above'}`} tabIndex="0" onMouseEnter={event=>positionPopover(index,event)} onFocus={event=>positionPopover(index,event)} key={index}><Icon/><span className="generation-reference-popover" role="tooltip"><i className="generation-reference-preview"><Icon/></i><b>{isImage?'图':'视频'}{index+1}</b></span></span>)}</div><div className={`generation-prompt-module ${hasPreview?'has-popover':'no-popover'}`}><button className="generation-prompt-summary"><Icon/><span>{prompt}</span></button>{hasPreview&&<div className="generation-prompt-detail" role="tooltip"><header><span><Icon/>{kind}</span></header><p>{prompt}</p><footer className="generation-input-details"><ParameterInfo/></footer></div>}</div><div className="generation-meta-inline generation-input-details"><ParameterInfo/></div><div className="media-output-footer"><div><button><Pencil/>重新编辑</button><button><RotateCcw/>再次生成</button><button><Trash2/>删除</button></div><time><Check/>2026/08/31.10:45</time></div></div>
}

function AgentInputAttachments({count=1}){const [popoverBelow,setPopoverBelow]=useState({});const positionPopover=(index,event)=>{const rect=event.currentTarget.getBoundingClientRect();setPopoverBelow(value=>({...value,[index]:rect.top<420}))};return <div className={`agent-input-attachments ${count>=2?'is-stacked':''}`} aria-label={`${count} 个输入附件`}>{Array.from({length:count},(_,index)=><span className={`generation-reference reference-image ${popoverBelow[index]?'popover-below':'popover-above'}`} tabIndex="0" onMouseEnter={event=>positionPopover(index,event)} onFocus={event=>positionPopover(index,event)} key={index}><Image/><span className="generation-reference-popover" role="tooltip"><i className="generation-reference-preview"><Image/></i><b>图{index+1}</b></span></span>)}</div>}

function AgentInputFooter({text,notify}){return <div className="agent-input-footer"><div><button onClick={()=>notify('已打开输入内容编辑')}><Pencil/>重新编辑</button><button onClick={()=>notify('已切换为 MD 格式')}><Code2/>MD格式</button><button onClick={()=>{navigator.clipboard?.writeText(text);notify('输入内容已复制')}}><Copy/>复制</button></div><div className="input-runtime-meta"><span><WandSparkles/>内容创作</span><i/><span><Bot/>Opus 4.6</span></div></div>}

function PromptLengthVideoStates({notify}){
 const [playing,setPlaying]=useState([false,false,false])
 const medium='镜头缓慢推进透明气泡水瓶，背景由深蓝过渡至紫色，气泡自然上升，柔和光线掠过瓶身，结尾定格品牌标识与夏日口号。'.slice(0,50)
 const long=('镜头从安静的深蓝空间开始，缓慢推进至画面中央的透明气泡水瓶。瓶身表面覆盖细腻冷凝水珠，清澈气泡从瓶底持续自然上升，背景色彩由深蓝逐渐过渡到明亮紫色。主光从左前方柔和扫过瓶身，形成干净通透的边缘高光，辅助光控制阴影层次，避免过曝和杂乱反射。镜头运动保持稳定克制，不使用剧烈摇晃、快速变焦或夸张转场。中段展示瓶身材质、标签细节与气泡流动，随后轻微环绕产品并拉开景别，为品牌标识和夏日主题文案留出安全区域。结尾让产品停留在视觉中心，背景光晕缓慢呼吸，品牌标识清晰出现并保持足够阅读时间。整体风格清爽、年轻、高级，具有真实商业广告质感，避免塑料感、廉价霓虹、复杂道具、人物遮挡和无关元素。画面需适配横屏视频、社交媒体裁切与移动端播放，保证不同尺寸下产品主体、标题和行动按钮都不会被裁掉。').repeat(4).slice(0,1000)
 const states=[['超短提示词','10 个字','镜头推进透明气泡水瓶'],['适中提示词','50 个字',medium],['超长提示词','1000 个字',long]]
 const toggle=index=>setPlaying(values=>values.map((value,i)=>i===index?!value:value))
 return <div className="unified-flow prompt-length-video-states">{states.map(([name,count,prompt],index)=><div className="message-row agent-row" key={count}><span className="agent-avatar flare"><GalleryHorizontalEnd/></span><div className="bubble agent-bubble media-bubble video-message"><div className="length-state-tag"><b>{name}</b><span>{count}</span></div><GenerationRecordHeader kind="视频生成输出" Icon={GalleryHorizontalEnd} prompt={prompt} model="Video Flow 2.1" params="16:9 · 1080P · 8 秒 · 24 FPS" time="1 分 26 秒" points="36"/><div className="generation-result-label"><span><GalleryHorizontalEnd/>输出结果</span></div><div className={`inline-video length-video-${index}`}><div className="video-scene"><span className="product-bottle"/><i/><i/><i/></div><button className="play-button" onClick={()=>toggle(index)}>{playing[index]?<Pause/>:<Play/>}</button><div className="inline-video-bar"><button onClick={()=>toggle(index)}>{playing[index]?<Pause/>:<Play/>}</button><span>00:03 / 00:08</span><i><b/></i><button onClick={()=>notify(`${name}已进入全屏预览`)}><Maximize2/></button></div></div><div className="inline-media-actions"><button onClick={()=>notify(`${name}已打开视频编辑器`)}><Pencil/>重新编辑</button><button onClick={()=>notify(`${name}已开始再次生成`)}><RotateCcw/>再次生成</button><button aria-label={`${name}更多视频操作`} onClick={()=>notify('更多操作已打开')}><MoreHorizontal/></button></div></div></div>)}</div>
}

function PromptLengthTextStates({notify}){
 const medium='请围绕新品气泡水撰写一套夏日发布文案，突出清爽口感、细腻气泡与轻盈活力，并给出主标题和一句行动号召。'.slice(0,50)
 const long=('请为新品气泡水策划一套完整的夏日发布内容。品牌希望传递轻盈、清爽、年轻和充满活力的感受，核心受众是关注生活品质与视觉审美的城市年轻人。文案需要兼顾品牌态度与产品卖点，清楚表达入口清爽、气泡细腻、低负担和适合多种生活场景等特点。请先提供一句具有记忆点的主标题，再补充一句简洁有力的副标题和一段适合社交媒体发布的正文。整体语气自然、有画面感，不过度夸张，不使用陈旧网络热词，也不要写成生硬的产品说明。内容需要能够与薄荷绿、湖水蓝和透明玻璃瓶组成的主视觉搭配，并适配电商横幅、社交媒体方图、竖版故事封面和短视频结尾画面。正文中可以描写打开瓶盖、气泡上升、冷凝水珠和夏日光线等细节，但要保持信息层级清晰。最后请提供一个直接但不过度促销的行动号召，并确保所有文字在移动端快速浏览时依然易读。').repeat(4).slice(0,1000)
 const longReply=('这套夏日发布内容以“轻盈气泡点亮日常”为核心叙事，从消费者打开瓶盖的瞬间切入，让清脆声响、细腻气泡和瓶身冷凝水珠共同构成清爽的感官记忆。主标题保持简短有力，方便在海报、横幅和视频结尾中快速识别；副标题补充产品口感与生活方式价值，使品牌态度和具体卖点自然连接。社交媒体正文从午后通勤、朋友聚会、户外散步和居家放松等真实场景展开，强调产品能够为普通时刻增加一点轻盈和活力，而不是使用夸张承诺。视觉语言延续薄荷绿、湖水蓝与透明玻璃材质，文案控制句子长度和信息层级，为移动端阅读保留清楚节奏。不同渠道可根据空间调整内容：电商横幅保留主标题与行动号召，社交媒体方图加入一句场景化描述，竖版故事封面强化情绪表达，详情页展开产品特点与品牌理念，短视频旁白则围绕开瓶、气泡上升、光线掠过瓶身和品牌定格四个节奏推进。所有版本保持自然、清爽、年轻但不过度讨好的语气，避免陈旧热词和生硬参数堆叠，让用户先感受到夏日氛围，再理解产品价值。行动号召采用邀请式表达，鼓励用户在此刻打开一瓶气泡水，为忙碌生活留出一段轻松、明亮、刚刚好的清爽间隙。').repeat(4).slice(0,1000)
 const states=[
  ['撰写清爽夏日品牌文案','已完成精简品牌文案。','清爽气泡，点亮夏天。','可直接使用。'],
  [medium,'结合产品卖点、夏日氛围与年轻用户的生活场景，整理了一版适合社交媒体和活动页面使用的发布文案。内容强调细腻气泡、清爽口感和轻盈体验，并保持自然、有画面感的品牌语气。','打开这一刻，让细腻气泡把清爽带进正在发光的夏天。','该版本可直接用于主视觉标题、社交媒体配文与活动页摘要，也可继续扩展为短视频旁白。'],
  [long,longReply,'让每一颗轻盈气泡，都成为夏日生活里刚刚好的清爽回应。','内容已经统一品牌语气、产品卖点、视觉方向与渠道表达，可继续拆分为海报标题、详情页文案、短视频旁白和完整发布说明。']
 ]
 return <div className="unified-flow prompt-length-text-states">{states.map(([prompt,intro,quote,closing],index)=><section className="prompt-length-text-group" key={index}><div className="message-row user-row"><div className="agent-input-message"><AgentInputAttachments count={index+1}/><div className="bubble user-bubble">{prompt}</div><AgentInputFooter text={prompt} notify={notify}/></div><span className="agent-avatar nova">N</span></div><div className="message-row agent-row"><span className="agent-avatar flare"><Bot/></span><div><div className="bubble agent-bubble"><span className="message-type"><MessageSquareText/>文本输出</span><p>{intro}</p><blockquote>{quote}</blockquote><p>{closing}</p></div><MessageFeedback text={`${intro}${quote}${closing}`} notify={notify}/></div></div></section>)}</div>
}

function PromptOutputBottomComposer({notify}){
 const [input,setInput]=useState('')
 const [sending,setSending]=useState(false)
 const send=()=>{if(sending){setSending(false);notify('已停止生成');return}if(!input.trim()){notify('请输入追问内容');return}setSending(true);setTimeout(()=>{setSending(false);setInput('');notify('追问已发送')},900)}
 return <div className="output-composer unified-composer prompt-output-bottom-composer"><textarea value={input} onChange={e=>setInput(e.target.value)} onKeyDown={e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter')send()}} placeholder="继续追问，或输入新的创作任务…"/><div><span><kbd>⌘</kbd><kbd>Enter</kbd> 发送</span><button className="icon-btn" onClick={()=>notify('附件选择器已打开')}><Paperclip/></button><button className={`send ${sending?'stop':''}`} onClick={send}>{sending?<Square/>:<ArrowUp/>}</button></div></div>
}

function PromptLengthStates({notify}){const [selected,setSelected]=useState([0,0,0]);const medium='为新品气泡水设计一张清爽夏日主视觉海报，透明瓶身置于薄荷绿渐变空间，使用柔和侧光与细腻气泡呈现高级商业质感。'.slice(0,50);const long=('为新品气泡水打造完整的夏日品牌视觉方案。画面中心是一只透明玻璃瓶，瓶身带有细腻冷凝水珠，清澈气泡从瓶底自然上升。背景采用薄荷绿、湖水蓝与柔和暖白组成的渐变空间，光线从左前方缓慢照入，在瓶身边缘形成干净通透的高光。构图需要留出品牌标识、主标题和卖点文案的安全区域，同时确保产品在不同裁切比例下仍然保持视觉中心。整体风格简洁、轻盈、年轻但不过度卡通，材质表现真实，避免塑料感、廉价感、复杂道具和杂乱背景。请分别考虑电商横幅、社交媒体方图、竖版故事封面和大屏展示的适配关系，保证色彩、字体、按钮和信息层级统一。人物若出现，应以自然生活方式状态作为陪衬，不遮挡产品，不使用夸张动作。输出画面需具有高端商业摄影质感，边缘清晰，阴影柔和，反射合理，并预留后续编辑空间。').repeat(4).slice(0,1000);const states=[['超短提示词','10 个字','生成清爽夏日产品海报'],['适中提示词','50 个字',medium],['超长提示词','1000 个字',long]];const options=[['image-a','1:1'],['image-b','3:4'],['image-c','4:3']];const choose=(group,image)=>setSelected(values=>values.map((value,index)=>index===group?image:value));return <section className="prompt-length-states"><header><div><b>提示词长度状态</b><small>三组完整图片输出，用于验证省略与悬停预览</small></div></header><div className="prompt-length-list">{states.map(([name,count,prompt],group)=><div className="message-row agent-row prompt-length-group" key={count}><span className="agent-avatar flare"><Image/></span><article className="bubble agent-bubble media-bubble image-message prompt-length-card"><div className="prompt-length-label"><b>{name}</b><span>{count}</span></div><GenerationRecordHeader kind="图片生成输出" Icon={Image} prompt={prompt} model="Image 5.0 Lite" params="3 张 · 1:1 / 3:4 / 4:3 · 2K" time="18 秒" points="12"/><div className="generation-result-label"><span><Image/>输出结果</span></div><div className="inline-image-grid">{options.map(([cls,ratio],image)=><div className={`image-option ratio-${ratio.replace(':','-')}`} key={ratio}><button className={`${cls} ${selected[group]===image?'selected':''}`} onClick={()=>choose(group,image)} aria-label={`选择${name}${ratio}图片`}><span>{selected[group]===image?<Check/>:image+1}</span></button><small>Aspect Ratio <i>/</i> <b>{ratio}</b></small></div>)}</div><div className="inline-media-actions"><button onClick={()=>notify(`${name}已打开图片编辑器`)}><Pencil/>重新编辑</button><button onClick={()=>notify(`${name}已开始再次生成`)}><RotateCcw/>再次生成</button><button aria-label={`${name}更多操作`} onClick={()=>notify('更多操作已打开')}><MoreHorizontal/></button></div></article></div>)}</div></section>}

function UnifiedPromptOutput({notify}){const [selectedImage,setSelectedImage]=useState(0);const [playing,setPlaying]=useState(false);const [input,setInput]=useState('');const [sending,setSending]=useState(false);const [followups,setFollowups]=useState([]);const imageOptions=[['image-a','1:1'],['image-b','3:4'],['image-c','4:3']];const send=()=>{if(sending){setSending(false);notify('已停止生成');return}const value=input.trim();if(!value){notify('请输入追问内容');return}setFollowups(x=>[...x,{role:'user',text:value}]);setInput('');setSending(true);setTimeout(()=>{setFollowups(x=>[...x,{role:'agent',text:'我会继续结合上面的文本、图片和视频结果进行处理，并保持相同的视觉方向。'}]);setSending(false)},1200)};return <div className="unified-feed"><div className="stream-header"><div><span className="agent-avatar flare"><Bot/></span><div><b>ShuLan Agent</b><small>多模态创作助手</small></div></div><span className="complete"><Check/>已连接</span></div><div className="unified-flow"><div className="message-row user-row"><div className="agent-input-message"><AgentInputAttachments count={2}/><div className="bubble user-bubble">为新品气泡水设计一套发布内容，包括文案、主视觉和短视频。</div></div><span className="agent-avatar nova">N</span></div><div className="message-row agent-row"><span className="agent-avatar flare"><Bot/></span><div><div className="bubble agent-bubble"><span className="message-type"><MessageSquareText/>文本输出</span><p>我会围绕“轻盈、清爽、充满活力”的主题完成整套发布内容。核心文案建议为：</p><blockquote>打开这一刻，让清爽气泡点亮整个夏天。</blockquote><p>下面是根据该方向生成的主视觉候选方案。</p></div><MessageFeedback text="打开这一刻，让清爽气泡点亮整个夏天。" notify={notify}/></div></div><div className="message-row agent-row"><span className="agent-avatar flare"><Image/></span><div className="bubble agent-bubble media-bubble image-message"><GenerationRecordHeader kind="图片生成输出" Icon={Image} prompt="未来主义气泡水产品摄影，透明瓶身置于薄荷绿渐变空间，柔和侧光，清爽夏日氛围，高级商业视觉。" model="Image 5.0 Lite" params="3 张 · 1:1 / 3:4 / 4:3 · 2K" time="18 秒" points="12"/><div className="generation-result-label"><span><Image/>输出结果</span><small>3 个候选结果</small></div><div className="inline-image-grid">{imageOptions.map(([cls,ratio],i)=><div className={`image-option ratio-${ratio.replace(':','-')}`} key={cls}><button className={`${cls} ${selectedImage===i?'selected':''}`} onClick={()=>setSelectedImage(i)} aria-label={`选择 ${ratio} 图片方案`}><span>{selectedImage===i?<Check/>:i+1}</span></button><small>Aspect Ratio <i>/</i> <b>{ratio}</b></small></div>)}</div><div className="inline-media-actions"><button onClick={()=>notify('已打开图片编辑器')}><Pencil/>重新编辑</button><button onClick={()=>notify('已开始再次生成图片')}><RotateCcw/>再次生成</button><button aria-label="更多图片操作" onClick={()=>notify('更多操作已打开')}><MoreHorizontal/></button></div></div></div><div className="message-row agent-row"><span className="agent-avatar flare"><GalleryHorizontalEnd/></span><div className="bubble agent-bubble media-bubble video-message"><GenerationRecordHeader kind="视频生成输出" Icon={GalleryHorizontalEnd} prompt="镜头缓慢推进透明气泡水瓶，背景由深蓝过渡至紫色，气泡自然上升，结尾定格品牌标识。" model="Video Flow 2.1" params="16:9 · 1080P · 8 秒 · 24 FPS" time="1 分 26 秒" points="36"/><div className="generation-result-label"><span><GalleryHorizontalEnd/>输出结果</span><small>版本 1 · 1080P</small></div><div className="inline-video"><div className="video-scene"><span className="product-bottle"/><i/><i/><i/></div><button className="play-button" onClick={()=>setPlaying(!playing)}>{playing?<Pause/>:<Play/>}</button><div className="inline-video-bar"><button onClick={()=>setPlaying(!playing)}>{playing?<Pause/>:<Play/>}</button><span>00:03 / 00:08</span><i><b/></i><button onClick={()=>notify('已进入全屏预览')}><Maximize2/></button></div></div><div className="inline-media-actions"><button onClick={()=>notify('已打开视频编辑器')}><Pencil/>重新编辑</button><button onClick={()=>notify('已开始再次生成视频')}><RotateCcw/>再次生成</button><button aria-label="更多视频操作" onClick={()=>notify('更多操作已打开')}><MoreHorizontal/></button></div></div></div>{followups.map((m,i)=>m.role==='user'?<div className="message-row user-row" key={i}><div className="bubble user-bubble">{m.text}</div><span className="agent-avatar nova">N</span></div>:<div className="message-row agent-row" key={i}><span className="agent-avatar flare"><Bot/></span><div className="bubble agent-bubble"><span className="message-type"><MessageSquareText/>文本输出</span><p>{m.text}</p></div></div>)}{sending&&<div className="message-row agent-row"><span className="agent-avatar flare"><Bot/></span><div className="bubble agent-bubble typing"><i/><i/><i/><span>正在生成多模态回复…</span></div></div>}</div><div className="output-composer unified-composer"><textarea value={input} onChange={e=>setInput(e.target.value)} onKeyDown={e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter')send()}} placeholder="继续追问，或输入新的创作任务…"/><div><span><kbd>⌘</kbd><kbd>Enter</kbd> 发送</span><button className="icon-btn" onClick={()=>notify('附件选择器已打开')}><Paperclip/></button><button className={`send ${sending?'stop':''}`} onClick={send}>{sending?<Square/>:<ArrowUp/>}</button></div></div></div>}

function MessageFeedback({text,notify}){return <div className="message-tools output-action-footer"><div><button onClick={()=>notify('已开始再次生成文本')}><RotateCcw/>再次生成</button><button onClick={()=>notify('已切换为 MD 格式')}><Code2/>MD格式</button><button onClick={()=>{navigator.clipboard?.writeText(text);notify('文本已复制')}}><Copy/>复制</button><button onClick={()=>notify('文本输出已删除')}><Trash2/>删除</button></div><time><Check/>2026/08/31.10:45</time></div>}

createRoot(document.getElementById('root')).render(<App />)
